import { useFrame } from '@react-three/fiber'
import { CuboidCollider, RigidBody } from '@react-three/rapier'
import {
  lazyModule,
  rng,
  sub,
  useNodeRenderer,
  useWorld,
  type WorldComponentProps,
} from '@runek/core'
import { useEffect, useMemo } from 'react'
import {
  AdditiveBlending,
  BufferAttribute,
  BufferGeometry,
  Color,
  InstancedBufferAttribute,
  ShaderMaterial,
} from 'three'
import { Sign } from './Sign'

// The WebGPU (TSL) twins of the shaders below, loaded only under a node renderer.
const portalNodes = lazyModule(() => import('./nodes/portal'))

export interface PortalProps extends WorldComponentProps {
  /**
   * Where the portal leads — a URL or app route. Kept JSON-serializable so a world
   * round-trips from data. With no `onEnter`, entering navigates here
   * (`window.location.href = to`); with `onEnter`, this is just passed through to it.
   */
  to?: string
  /**
   * Called once when the avatar (or a vehicle) enters the gate, with `to`. Optional, so
   * the component still renders and round-trips from data without it (CONTRACT §1). Use it
   * to drive an in-app transition instead of a full navigation — e.g. swap the mounted world.
   * Note: a host rendered inside `<WorldRenderer>` lives in a separate React reconciler from
   * the page, so bridge this callback out through a module-level store, not React context.
   */
  onEnter?: (to: string | undefined) => void
  /** Floating caption above the gate (e.g. the destination's name). */
  label?: string
  /** Radius of the swirling vortex around the dark core, in units. */
  radius?: number
  /** Glow / swirl color; defaults to the world palette's `accent` slot. */
  color?: string
  /** Arm the trigger. Set false for a decorative or not-yet-open gate. Default true. */
  active?: boolean
}

// rapier RigidBody types: 0 Dynamic, 1 Fixed, 2 KinematicPosition, 3 KinematicVelocity.
const FIXED = 1
// `ActiveCollisionTypes`: DEFAULT (15) covers a dynamic body (the on-foot avatar) vs anything;
// OR in KINEMATIC_FIXED (8704) so the gate also fires for a kinematic vehicle (a boat, a cart)
// against this fixed sensor. The avatar capsule is dynamic; a scripted vehicle is kinematic.
const TRIGGER_TYPES = 15 | 8704

// The vortex quad reaches past the swirl so the halo can fade out; in multiples of `radius`.
const EXTENT = 1.9
const MOTES = 80

// Everything is drawn camera-facing around the gate's center, so the hole reads as a sphere
// of darkness from any side rather than a flat disc.
const VORTEX_VERTEX = /* glsl */ `
uniform float uR;
uniform float uExtent;
varying vec2 vP;
void main() {
  vP = position.xy * uExtent;
  vec4 mv = modelViewMatrix * vec4(0.0, 0.0, 0.0, 1.0);
  mv.xy += position.xy * uExtent * uR;
  gl_Position = projectionMatrix * mv;
}`

const VORTEX_FRAGMENT = /* glsl */ `
uniform float uTime;
uniform float uSeed;
uniform vec3 uHot;
uniform vec3 uCool;
varying vec2 vP;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 4; i++) { v += a * noise(p); p = p * 2.03 + 17.1; a *= 0.5; }
  return v;
}
// Rotate a point by an angle that grows toward the center: sampled noise becomes spiral arms.
vec2 twirl(vec2 p, float r, float k, float t) {
  float a = k / (r + 0.15) + t;
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c) * p;
}

void main() {
  float r = length(vP);
  const float h = 0.42;

  float arms = mix(
    fbm(twirl(vP, r, 2.2, uTime * 0.7) * 2.4 + uSeed),
    fbm(twirl(vP, r, 3.6, uTime * 1.4) * 4.2 - uSeed),
    0.45
  );
  arms = smoothstep(0.3, 0.85, arms);

  float outside = smoothstep(h - 0.012, h + 0.012, r);
  float disc = outside * exp(-(r - h) * 2.4) * (1.0 - smoothstep(0.95, 1.3, r));
  float ring = exp(-pow((r - h * 1.04) / 0.022, 2.0));
  float halo = outside * exp(-(r - h) * 1.7) * (1.0 - smoothstep(1.3, 1.9, r));
  float pulse = 0.85 + 0.15 * sin(uTime * 1.3 + r * 6.0);

  float heat = exp(-(r - h) * 5.0);
  vec3 tint = mix(uCool, uHot, clamp(heat, 0.0, 1.0));
  vec3 light = tint * (disc * arms * 3.0 + halo * 0.4 * pulse)
             + mix(uHot, vec3(1.0), 0.6) * ring * 1.6;

  // A faint wisp of light still curling inside the horizon gives the dark core depth.
  float inner = (1.0 - outside) * pow(r / h, 6.0) * arms * 0.25;
  light += uCool * inner;

  // Premultiplied: the core occludes what's behind it, the glow adds on top.
  float shadow = (1.0 - smoothstep(h, h * 1.8, r)) * 0.6;
  float alpha = max(1.0 - outside, clamp(disc * arms * 0.7 + shadow * outside, 0.0, 0.95));
  gl_FragColor = vec4(light, alpha);
}`

const MOTE_VERTEX = /* glsl */ `
uniform float uTime;
uniform float uR;
uniform float uSize;
uniform float uHalfHeight;
attribute vec3 aMote;
varying float vFade;
void main() {
  float life = fract(aMote.y + uTime * aMote.z);
  float r = mix(1.45, 0.44, life * life);
  float a = aMote.x - 2.2 / (r + 0.15) - uTime * 0.7;
  vec4 mv = modelViewMatrix * vec4(0.0, 0.0, 0.0, 1.0);
  mv.xy += vec2(cos(a), sin(a)) * r * uR;
  gl_Position = projectionMatrix * mv;
  vFade = smoothstep(0.0, 0.25, life) * (1.0 - smoothstep(0.85, 1.0, life));
  gl_PointSize = uSize * (0.6 + life) * projectionMatrix[1][1] * uHalfHeight / -mv.z;
}`

const MOTE_FRAGMENT = /* glsl */ `
uniform vec3 uColor;
varying float vFade;
void main() {
  float d = length(gl_PointCoord - 0.5);
  gl_FragColor = vec4(uColor * smoothstep(0.5, 0.0, d) * vFade, 1.0);
}`

const POOL_VERTEX = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`

const POOL_FRAGMENT = /* glsl */ `
uniform vec3 uColor;
varying vec2 vUv;
void main() {
  float r = length(vUv - 0.5) * 2.0;
  float a = pow(max(1.0 - r, 0.0), 2.2) * 0.45;
  gl_FragColor = vec4(uColor * a, 1.0);
}`

/**
 * A travel gate: a swirling vortex around a lightless core, wrapped in a soft glow, that
 * fires a one-shot event when the avatar — or a vehicle — passes through it. The visual is
 * procedural and asset-free (the seed shapes the swirl and the drifting motes); the trigger
 * is a Rapier sensor. Drive transitions with the optional `onEnter` callback, or set `to` and
 * let it navigate. Use it for world-to-world travel, level/hub transitions, or in-world
 * teleports; for a single continuous space, move the camera instead.
 */
export function Portal({
  to,
  onEnter,
  label,
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  seed = 1,
  radius = 2.2,
  color,
  active = true,
}: PortalProps) {
  const { unit, palette } = useWorld()
  const ink = color ?? palette.accent
  const R = radius * unit
  const nodes = useNodeRenderer() ? portalNodes() : null

  const vortex = useMemo(() => {
    const hot = new Color(ink)
    const cool = hot.clone().offsetHSL(0.1, 0.05, -0.12)
    const uniforms = {
      uTime: { value: 0 },
      uR: { value: R },
      uExtent: { value: EXTENT },
      uSeed: { value: rng(sub(seed, 0))() * 100 },
      uHot: { value: hot },
      uCool: { value: cool },
    }
    const material = nodes
      ? nodes.vortexMaterial(uniforms)
      : new ShaderMaterial({
          vertexShader: VORTEX_VERTEX,
          fragmentShader: VORTEX_FRAGMENT,
          uniforms,
          transparent: true,
          premultipliedAlpha: true,
          depthWrite: false,
          toneMapped: false,
        })
    return { material, uniforms }
  }, [ink, R, seed, nodes])

  const motes = useMemo(() => {
    const r = rng(sub(seed, 1))
    const data = new Float32Array(MOTES * 3)
    for (let i = 0; i < MOTES; i++) {
      data[i * 3] = r() * Math.PI * 2
      data[i * 3 + 1] = r()
      data[i * 3 + 2] = 0.08 + r() * 0.14
    }
    const uniforms = {
      uTime: { value: 0 },
      uR: { value: R },
      uSize: { value: 0.07 * R },
      uHalfHeight: { value: 400 },
      uColor: { value: new Color(ink).lerp(new Color('#ffffff'), 0.35) },
    }
    if (nodes) {
      // WebGPU draws points a pixel wide: instanced quads instead.
      const geometry = nodes.pointQuads(MOTES, { aMote: new InstancedBufferAttribute(data, 3) })
      return { geometry, material: nodes.portalMotesMaterial(uniforms), uniforms, quads: true }
    }
    const geometry = new BufferGeometry()
    geometry.setAttribute('position', new BufferAttribute(new Float32Array(MOTES * 3), 3))
    geometry.setAttribute('aMote', new BufferAttribute(data, 3))
    const material = new ShaderMaterial({
      vertexShader: MOTE_VERTEX,
      fragmentShader: MOTE_FRAGMENT,
      uniforms,
      transparent: true,
      blending: AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    })
    return { geometry, material, uniforms, quads: false }
  }, [ink, R, seed, nodes])

  const pool = useMemo(() => {
    const uniforms = { uColor: { value: new Color(ink) } }
    return nodes
      ? nodes.poolMaterial(uniforms, 0.45)
      : new ShaderMaterial({
          vertexShader: POOL_VERTEX,
          fragmentShader: POOL_FRAGMENT,
          uniforms,
          transparent: true,
          blending: AdditiveBlending,
          depthWrite: false,
          toneMapped: false,
        })
  }, [ink, nodes])

  useEffect(
    () => () => {
      vortex.material.dispose()
      motes.material.dispose()
      motes.geometry.dispose()
      pool.dispose()
    },
    [vortex, motes, pool],
  )

  useFrame(({ clock, size, viewport }) => {
    const t = clock.elapsedTime
    vortex.uniforms.uTime.value = t
    motes.uniforms.uTime.value = t
    motes.uniforms.uHalfHeight.value = (size.height * viewport.dpr) / 2
  })

  return (
    <RigidBody type="fixed" colliders={false} position={position} rotation={rotation}>
      {/* A generous sensor around the gate; deep enough on the approach axis that a fast
          vehicle can't tunnel through between frames. Ignores Fixed bodies (terrain, props),
          so it never fires against the ground it stands on. */}
      <CuboidCollider
        sensor
        activeCollisionTypes={TRIGGER_TYPES}
        args={[R * 1.1, R + 0.6 * unit, Math.max(R, 1.6 * unit)]}
        position={[0, R, 0]}
        onIntersectionEnter={({ other }) => {
          if (!active || !other.rigidBody || other.rigidBody.bodyType() === FIXED) return
          if (onEnter) onEnter(to)
          else if (to) window.location.href = to
        }}
      />

      <group position={[0, R, 0]}>
        <mesh material={vortex.material} renderOrder={1} frustumCulled={!nodes}>
          <planeGeometry args={[2, 2]} />
        </mesh>
        {motes.quads ? (
          <mesh
            geometry={motes.geometry}
            material={motes.material}
            frustumCulled={false}
            renderOrder={2}
          />
        ) : (
          <points
            geometry={motes.geometry}
            material={motes.material}
            frustumCulled={false}
            renderOrder={2}
          />
        )}
      </group>

      {/* Light spilling onto the ground beneath the vortex. */}
      <mesh position={[0, 0.02 * unit, 0]} rotation={[-Math.PI / 2, 0, 0]} material={pool}>
        <planeGeometry args={[R * 2.8, R * 2.8]} />
      </mesh>

      {label && (
        <Sign position={[0, R * 2 + 0.9 * unit, 0]} size={0.7} color={ink} glow>
          {label}
        </Sign>
      )}
    </RigidBody>
  )
}

import {
  AdditiveBlending,
  type BufferGeometry,
  type Color,
  type InstancedBufferAttribute,
  InstancedBufferGeometry,
  PlaneGeometry,
} from 'three'
import {
  attribute,
  cameraProjectionMatrix,
  clamp,
  cos,
  exp,
  float,
  fract,
  length,
  max,
  mix,
  modelViewMatrix,
  positionGeometry,
  pow,
  sin,
  smoothstep,
  sRGBTransferEOTF,
  uv,
  varying,
  vec2,
  vec3,
  vec4,
} from 'three/tsl'
import { MeshBasicNodeMaterial, type Node } from 'three/webgpu'
import { fbm } from './noise'
import { follow } from './uniforms'

type F = Node<'float'>
type V2 = Node<'vec2'>
type V3 = Node<'vec3'>

const eotf = (c: Node) => sRGBTransferEOTF(c) as V3

/** A point `offset` (in view units) from the object's center, facing the camera: the clip
 *  position the GLSL computes as `projectionMatrix * (modelViewMatrix * origin + offset)`. */
export function facing(offset: V2) {
  const center = modelViewMatrix.mul(vec4(0, 0, 0, 1))
  return cameraProjectionMatrix.mul(center.add(vec4(offset, 0, 0)))
}

/** Rotate `p` by an angle growing toward the center: noise sampled through it spirals. */
function twirl(p: V2, r: F, k: number, t: F): V2 {
  const a = float(k).div(r.add(0.15)).add(t)
  const c = cos(a)
  const s = sin(a)
  return vec2(c.mul(p.x).add(s.mul(p.y)), s.negate().mul(p.x).add(c.mul(p.y))) as V2
}

export interface VortexUniforms {
  uTime: { value: number }
  uR: { value: number }
  uExtent: { value: number }
  uSeed: { value: number }
  uHot: { value: Color }
  uCool: { value: Color }
}

/** The node (TSL) twin of `Portal`'s vortex. */
export function vortexMaterial(record: VortexUniforms) {
  const time = follow<F>(record.uTime)
  const R = follow<F>(record.uR)
  const extent = follow<F>(record.uExtent)
  const seed = follow<F>(record.uSeed)
  const hot = follow<V3>(record.uHot)
  const cool = follow<V3>(record.uCool)

  const p = varying(positionGeometry.xy.mul(extent)) as V2
  const r = length(p) as F
  const h = 0.42
  let arms = mix(
    fbm(twirl(p, r, 2.2, time.mul(0.7)).mul(2.4).add(seed) as V2, 4, 2.03, 17.1),
    fbm(twirl(p, r, 3.6, time.mul(1.4)).mul(4.2).sub(seed) as V2, 4, 2.03, 17.1),
    0.45,
  ) as F
  arms = smoothstep(0.3, 0.85, arms) as F
  const outside = smoothstep(h - 0.012, h + 0.012, r)
  const disc = outside.mul(exp(r.sub(h).mul(-2.4))).mul(smoothstep(0.95, 1.3, r).oneMinus())
  const ring = exp(pow(r.sub(h * 1.04).div(0.022), 2).negate())
  const halo = outside.mul(exp(r.sub(h).mul(-1.7))).mul(smoothstep(1.3, 1.9, r).oneMinus())
  const pulse = sin(time.mul(1.3).add(r.mul(6)))
    .mul(0.15)
    .add(0.85)
  const heat = exp(r.sub(h).mul(-5))
  const tint = mix(cool, hot, clamp(heat, 0, 1)) as V3
  let light = tint
    .mul(disc.mul(arms).mul(3).add(halo.mul(0.4).mul(pulse)))
    .add(mix(hot, vec3(1), 0.6).mul(ring).mul(1.6)) as V3
  const inner = outside
    .oneMinus()
    .mul(pow(r.div(h), 6))
    .mul(arms)
    .mul(0.25)
  light = light.add(cool.mul(inner)) as V3
  const shadow = smoothstep(h, h * 1.8, r)
    .oneMinus()
    .mul(0.6)
  const alpha = max(
    outside.oneMinus(),
    clamp(disc.mul(arms).mul(0.7).add(shadow.mul(outside)), 0, 0.95),
  )

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    premultipliedAlpha: true,
    depthWrite: false,
  })
  material.vertexNode = facing(positionGeometry.xy.mul(extent).mul(R) as V2)
  // The GLSL writes its color as is; undo the node pipeline's sRGB output conversion to match.
  material.colorNode = vec4(eotf(light), alpha)
  material.toneMapped = false
  return material
}

/**
 * Sized points for `WebGPURenderer`, which draws `Points` one pixel wide: one camera-facing quad
 * per point, instanced. `attributes` become per-instance attributes of the same names.
 */
export function pointQuads(count: number, attributes: Record<string, InstancedBufferAttribute>) {
  const quad = new PlaneGeometry(1, 1)
  const geometry = new InstancedBufferGeometry()
  geometry.index = quad.index
  geometry.setAttribute('position', quad.getAttribute('position'))
  geometry.setAttribute('uv', quad.getAttribute('uv'))
  for (const [name, attr] of Object.entries(attributes)) geometry.setAttribute(name, attr)
  geometry.instanceCount = count
  return geometry as BufferGeometry
}

export interface PortalMoteUniforms {
  uTime: { value: number }
  uR: { value: number }
  uSize: { value: number }
  uColor: { value: Color }
}

/** The node (TSL) twin of `Portal`'s drifting motes, drawn on `pointQuads`. */
export function portalMotesMaterial(record: PortalMoteUniforms) {
  const time = follow<F>(record.uTime)
  const R = follow<F>(record.uR)
  const size = follow<F>(record.uSize)
  const color = follow<V3>(record.uColor)
  const mote = attribute('aMote', 'vec3') as V3
  const life = fract(mote.y.add(time.mul(mote.z))) as F
  const r = mix(1.45, 0.44, life.mul(life)) as F
  const a = mote.x.sub(float(2.2).div(r.add(0.15))).sub(time.mul(0.7))
  const span = size.mul(life.add(0.6))
  const offset = vec2(cos(a), sin(a)).mul(r).mul(R).add(positionGeometry.xy.mul(span)) as V2
  const fade = varying(smoothstep(0, 0.25, life).mul(smoothstep(0.85, 1, life).oneMinus())) as F
  const d = length(uv().sub(0.5))

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
  })
  material.vertexNode = facing(offset)
  material.colorNode = vec4(eotf(color.mul(smoothstep(0.5, 0, d)).mul(fade)), 1)
  material.toneMapped = false
  return material
}

/** The node (TSL) twin of a portal's or rift's glow pooled on the ground. */
export function poolMaterial(
  record: { uColor: { value: Color }; uOpen?: { value: number } },
  strength: number,
) {
  const color = follow<V3>(record.uColor)
  const open = record.uOpen ? follow<F>(record.uOpen) : float(1)
  const r = length(uv().sub(0.5)).mul(2)
  const a = pow(max(r.oneMinus(), 0), 2.2).mul(strength).mul(open)
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
  })
  // Added over a lit floor: blended in linear light here (display values in WebGL), so the color
  // goes in as is rather than converted, which lands closer to how bright WebGL's glow reads.
  material.colorNode = vec4(color.mul(a), 1)
  material.toneMapped = false
  return material
}

import { dot, float, floor, fract, mix, sin, vec2 } from 'three/tsl'
import type { Node } from 'three/webgpu'

type V2 = Node<'vec2'>
type F = Node<'float'>

/** The GLSL `hash` the shader components share: a pseudo-random 0..1 per point. */
export function hash(p: V2): F {
  return fract(sin(dot(p, vec2(127.1, 311.7))).mul(43758.5453)) as F
}

/** Smooth value noise, 0..1. */
export function noise(p: V2): F {
  const i = floor(p) as V2
  const f = fract(p) as V2
  const u = f.mul(f).mul(f.mul(-2).add(3)) as V2
  const a = hash(i)
  const b = hash(i.add(vec2(1, 0)) as V2)
  const c = hash(i.add(vec2(0, 1)) as V2)
  const d = hash(i.add(vec2(1, 1)) as V2)
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y) as F
}

/** Fractal noise: `octaves` layers, each `lacunarity` times finer and shifted by `shift`. */
export function fbm(p: V2, octaves: number, lacunarity: number, shift: number): F {
  let v: F = float(0)
  let q: V2 = p
  let a = 0.5
  for (let i = 0; i < octaves; i++) {
    v = v.add(noise(q).mul(a)) as F
    q = q.mul(lacunarity).add(shift) as V2
    a *= 0.5
  }
  return v
}

import { uniform } from 'three/tsl'
import type { Node } from 'three/webgpu'

/** A TSL uniform that follows `entry.value` every render, so the `{ value }` records a
 *  component already updates (for its GLSL material) drive its node material too. */
export function follow<N extends Node>(entry: { value: unknown }): N {
  return uniform(entry.value as never).onRenderUpdate(() => entry.value as never) as unknown as N
}
